function renderLevel2(){const courses=window.LAW_LEVEL2;let record={};try{record=JSON.parse(localStorage.getItem(L2_KEY)||'{}')||{}}catch(e){}const esc=s=>String(s).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;');const save=()=>{try{localStorage.setItem(L2_KEY,JSON.stringify(record));return true}catch(e){return false}};
const home=()=>{shell('<div class="pagehead"><span class="gold-label">LEVEL 2 · FIRST-YEAR LAW</span><h1>1L Core Curriculum</h1><p>Seven foundational subjects. Initial authored modules are available; the full 1L syllabus remains in development.</p></div><div class="level-list">'+courses.map((c,i)=>'<button class="level-row" data-l2course="'+i+'"><span class="level-icon">'+(i+1)+'</span><span class="level-text"><strong>'+esc(c.title)+'</strong><small>'+c.lessons.filter(l=>record[l.id]?.correct).length+' / '+c.lessons.length+' lesson checks passed</small></span><span class="level-arrow">›</span></button>').join('')+'</div><button id="l2realcases" class="gold-button">Real court cases · predict the outcome</button><button id="l2exam" class="gold-button">Timed 1L writing exam</button><button id="l2back" class="button secondary">Back to Academy</button>','courses');document.querySelectorAll('[data-l2course]').forEach(b=>b.onclick=()=>showCourse(+b.dataset.l2course));document.querySelector('#l2back').onclick=renderCatalog;document.querySelector('#l2exam').onclick=()=>showExam();document.querySelector('#l2realcases').onclick=()=>showRealCases();};
const showExam=()=>{const prompts=[
['Contracts','A retail buyer orders 500 chairs at $65 each for delivery December 10. A manufacturer acknowledges the order but changes delivery to December 20 and adds arbitration. Both are merchants. Buyer accepts December 20 delivery and claims lost promotional sales. Analyze UCC formation, additional and different terms, performance, provable damages, and each side’s strongest argument.'],
['Torts','A hotel receives a loose-stair-rail report at 8 a.m. and schedules repair for 4 p.m. At noon a guest falls, claiming the rail detached. A witness says luggage caused the trip. Analyze applicable duty, notice, breach, competing causes, damages, comparative fault and evidence required.'],
['Civil Procedure','An Illinois citizen sues a Texas citizen in federal court in Texas for $90,000. Defendant disputes personal jurisdiction and venue. Plaintiff also wants to sue a Texas company on another contract. Distinguish citizenship, diversity, amount, claims, personal jurisdiction, venue and available procedural motions.'],
['Criminal Law','A worker takes a laptop from the storage room, claiming it was assigned to them. A coworker reports an earlier statement about selling it. The jurisdiction requires knowingly taking another person’s property with intent to deprive. Evaluate offense elements, mistake of fact, conflicting evidence, burdens of proof and competing conclusions.'],
['Constitutional Law','A state university allows registered student groups to book meeting rooms. It denies an invitation to a controversial speaker citing safety and staffing, although a comparably sized event expressing opposing views was allowed. Analyze forum classification, viewpoint bias, neutral rationales, disputed evidence and relief.'],
['Property','Before subdivision, the owner used a gravel driveway across the southern parcel to reach the northern parcel. The southern buyer later blocks access; another possible route needs costly construction. Analyze express, implied, necessity and prescriptive easements, scope, notice and governing state law.'],
['Legal Research & Writing','A client asks about auto-renewing subscriptions. A state consumer statute was amended after two appellate cases, contains an industry exception and may have a delayed effective date. Draft an objective memo outline, current-law research plan, history and subsequent-treatment checks, adverse authority discussion and missing-fact list.']
];const key='law-academy-level2-exam-v1';const metaKey='law-academy-level2-exam-timing-v1';const limit=140*60*1000;let timing={};try{timing=JSON.parse(localStorage.getItem(metaKey)||'{}')||{}}catch(e){};if(!Number.isFinite(timing.startedAt)){timing={startedAt:Date.now(),submittedAt:null};try{localStorage.setItem(metaKey,JSON.stringify(timing))}catch(e){}}let answers={};try{answers=JSON.parse(localStorage.getItem(key)||'{}')||{}}catch(e){};shell('<div class="pagehead"><span class="gold-label">FORMATIVE · LEVEL 2</span><h1>Timed 1L Writing Exam</h1><p>Seven original issue-spotting prompts, suggested 140 minutes total. This is ungraded practice; it is not the held-out bar examination.</p></div>'+prompts.map((p,i)=>'<div class="review-item"><h3>'+(i+1)+'. '+p[0]+'</h3><p>'+p[1]+'</p><label for="l2exam'+i+'">Issue, rule, application, counterargument, conclusion</label><textarea class="writing-field" rows="7" id="l2exam'+i+'"></textarea></div>').join('')+'<p id="l2examClock" role="timer">Suggested writing window: 140 minutes</p><button id="l2examSubmit" class="gold-button">Submit practice attempt</button><p id="l2examStatus" role="status">Drafts saved on this device as you type.</p><button id="l2examBack" class="button secondary">Back to Level 2</button>','courses');const elapsed=Math.max(0,Date.now()-timing.startedAt);const clock=document.querySelector('#l2examClock');const remaining=Math.max(0,Math.ceil((limit-elapsed)/60000));clock.textContent=timing.submittedAt?'Attempt submitted for independent review.':(remaining?remaining+' minutes remain in suggested window.':'Suggested 140-minute window elapsed. You may continue practicing.');const submit=document.querySelector('#l2examSubmit');const status=document.querySelector('#l2examStatus');const fields=()=>prompts.map((_,i)=>document.querySelector('#l2exam'+i));const lock=()=>{fields().forEach(x=>x.disabled=true);submit.disabled=true};if(timing.submittedAt)lock();submit.onclick=()=>{const written=fields().filter(x=>x.value.trim()).length;if(written!==7){status.textContent='Complete all seven responses before submission ('+written+'/7 present).';return}timing.submittedAt=Date.now();try{localStorage.setItem(metaKey,JSON.stringify(timing));lock();clock.textContent='Attempt submitted for independent review.';status.textContent='Submitted locally. No score is assigned automatically.'}catch(e){timing.submittedAt=null;status.textContent='Unable to save submission. Copy answers before leaving.'}};prompts.forEach((p,i)=>{const field=document.querySelector('#l2exam'+i);field.value=answers[i]||'';field.oninput=()=>{answers[i]=field.value;try{localStorage.setItem(key,JSON.stringify(answers))}catch(e){document.querySelector('#l2examStatus').textContent='Storage unavailable. Copy your answers before leaving.'}}});document.querySelector('#l2examBack').onclick=home};
const REAL_CASES=[{"course":"Contracts","name":"Lucy v. Zehmer","court":"Supreme Court of Virginia (1954)","source":"https://law.justia.com/cases/virginia/supreme-court/1954/4272-1.html","facts":"A buyer and sellers signed a writing for sale of a farm after drinking together. The sellers later said it was all a joke. The buyer understood a serious bargain had been struck.","question":"Should a party's undisclosed claim that they were joking automatically defeat the apparent agreement?","options":["Yes, whenever a party privately intended a joke","No; a court considers reasonable outward words and conduct","Yes, because land contracts never can be enforced"],"answer":1,"outcome":"The Virginia Supreme Court found an enforceable agreement based on objective manifestations of assent and directed specific performance. The sellers' undisclosed intent to joke did not control.","reason":"Objective contract formation focuses on reasonably communicated conduct; intoxication and equitable remedy arguments still require factual analysis.","task":"Write an IRAC paragraph distinguishing a private joke from objectively apparent assent."},{"course":"Torts","name":"Palsgraf v. Long Island Railroad Co.","court":"New York Court of Appeals (1928)","source":"https://law.justia.com/cases/new-york/court-of-appeals/1928/248-n-y-339-1928.html","facts":"Railroad workers helped a passenger board a moving train. His package fell, containing concealed fireworks. The explosion caused scales to fall some distance away and injure a bystander.","question":"Under the majority's approach, was the railroad liable to this injured passenger?","options":["No; the majority found no duty to this unforeseeable plaintiff","Yes, every negligent act creates unlimited liability","Yes, because negligence never requires duty"],"answer":0,"outcome":"The New York Court of Appeals reversed for the railroad. Chief Judge Cardozo's majority reasoned the risk to this plaintiff was not reasonably foreseeable; Judge Andrews dissented with a broader duty approach.","reason":"Separate a duty owed to the plaintiff from careless conduct directed toward someone else, and examine the dissent's approach.","task":"Compare the majority's duty analysis with the dissent's proximate-cause framework."},{"course":"Civil Procedure","name":"International Shoe Co. v. Washington","court":"U.S. Supreme Court (1945)","source":"https://www.law.cornell.edu/supremecourt/text/326/310","facts":"A Delaware shoe company had no Washington office, but employed sales representatives who continuously solicited orders there. Washington sought unpaid unemployment-fund contributions.","question":"Could Washington assert personal jurisdiction based on the company's in-state activities?","options":["No, only a corporation's incorporation state can hear such claims","Yes, systematic forum contacts connected to the claim supported jurisdiction","No, unless the company rented its headquarters in Washington"],"answer":1,"outcome":"The U.S. Supreme Court upheld Washington's exercise of jurisdiction. The company's continuous in-state activity generated obligations connected to that activity.","reason":"The minimum-contacts and fairness analysis depends on the quality, nature, and connection of contacts to the dispute; later decisions have refined the doctrine.","task":"Identify the forum contacts and explain why this decision does not authorize jurisdiction over every unrelated claim."},{"course":"Criminal Law","name":"Gideon v. Wainwright","court":"U.S. Supreme Court (1963)","source":"https://www.law.cornell.edu/supremecourt/text/372/335","facts":"Clarence Gideon, unable to afford counsel, was denied an appointed lawyer at his Florida state felony trial and represented himself. He was convicted and challenged that denial.","question":"Did the Constitution require appointed counsel for an indigent defendant in this state felony prosecution?","options":["No, appointed lawyers are required only in federal prosecutions","No, a person always must retain private counsel","Yes; the Sixth Amendment right applies to state felony prosecutions through the Fourteenth Amendment"],"answer":2,"outcome":"The U.S. Supreme Court unanimously reversed, holding that counsel must be provided for indigent defendants in state felony prosecutions and overruling Betts v. Brady.","reason":"Connect the Sixth Amendment guarantee with incorporation under the Fourteenth Amendment; later case law governs other prosecution categories.","task":"Explain the constitutional rule and the consequences of denial of appointed counsel."},{"course":"Constitutional Law","name":"Riley v. California","court":"U.S. Supreme Court (2014)","source":"https://www.law.cornell.edu/supremecourt/text/13-132","facts":"Police seized a smartphone during a lawful arrest and accessed its digital contents without first obtaining a warrant, citing the search-incident-to-arrest exception.","question":"Does a lawful arrest alone generally allow a warrantless search of the phone's digital contents?","options":["Yes, all data is automatically searchable","No; police generally need a warrant absent another exception","Yes, but only for newer phones"],"answer":1,"outcome":"The U.S. Supreme Court held that officers generally must obtain a warrant to search digital information on a seized cellphone incident to arrest, subject to other recognized exceptions.","reason":"The privacy implications of vast digital data differ from ordinary physical items; narrowly assess any actual exigency.","task":"Explain the difference between seizing a phone and searching its digital contents."}];
const showRealCases=()=>{const esc=s=>String(s).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;');shell('<div class="pagehead"><span class="gold-label">LEVEL 2 · ACTUAL COURT DECISIONS</span><h1>Decide the Real Case</h1><p>Real parties and verified historical decisions. Make your prediction before revealing the outcome. These holdings are contextual, not a substitute for current-law research.</p></div>'+REAL_CASES.map((c,i)=>'<div class="review-item"><h3>'+esc(c.course)+' · '+esc(c.name)+'</h3><p>'+esc(c.court)+'</p><p>'+esc(c.facts)+'</p><p><strong>Decision question:</strong> '+esc(c.question)+'</p>'+c.options.map((o,k)=>'<label style="display:block;margin:9px 0"><input type="radio" name="realcase'+i+'" value="'+k+'"> '+esc(o)+'</label>').join('')+'<label for="realcaseDraft'+i+'">Explain your reasoning before revealing the outcome</label><textarea id="realcaseDraft'+i+'" class="writing-field" rows="4"></textarea><button class="gold-button" data-reveal="'+i+'">Reveal what the court decided</button><div id="realcaseResult'+i+'" role="status"></div></div>').join('')+'<button id="realcaseBack" class="button secondary">Back to Level 2</button>','courses');document.querySelectorAll('[data-reveal]').forEach(b=>b.onclick=()=>{const i=+b.dataset.reveal,c=REAL_CASES[i];const choice=document.querySelector('input[name="realcase'+i+'"]:checked');const draft=document.querySelector('#realcaseDraft'+i).value.trim();const target=document.querySelector('#realcaseResult'+i);if(!choice||!draft){target.textContent='Select a prediction and explain your reasoning first.';return}target.textContent='';const p=document.createElement('p');p.textContent=(+choice.value===c.answer?'Your prediction matches the decision. ':'Your prediction differs from the decision. ')+c.outcome+' Why: '+c.reason+' Writing challenge: '+c.task;target.append(p);const link=document.createElement('a');link.href=c.source;link.target='_blank';link.rel='noopener noreferrer';link.textContent='Read the original court decision';target.append(link);b.disabled=true});document.querySelector('#realcaseBack').onclick=home};
const INLINE_CASES=[...REAL_CASES.filter(c=>c.course!=='Criminal Law'),{course:'Criminal Law',name:'Morissette v. United States',court:'U.S. Supreme Court (1952)',facts:'A defendant collected discarded bomb casings from a government range, claiming he believed the materials abandoned.',question:'Could criminal intent be disregarded merely because the federal statute was silent?',outcome:'The Supreme Court reversed, requiring proper treatment of intent for this theft-like offense.',reason:'Traditional theft-related crimes generally require a culpable mental state; assess statutory language and exceptions.',source:'https://www.law.cornell.edu/supremecourt/text/342/246',task:'Analyze intent, mistake of fact and how the jury should be instructed.'},{course:'Property',name:'Pierson v. Post',court:'New York Supreme Court of Judicature (1805)',facts:'One hunter pursued a fox; another intercepted and killed it, leading to a dispute over who first acquired ownership.',question:'Was pursuit without capture sufficient to establish ownership of the fox?',outcome:'The majority held mere pursuit insufficient. The dissent favored the pursuing hunter.',reason:'The case illustrates acquisition by possession of wild animals, not a rule about estates in land.',source:'https://history.nycourts.gov/case/pierson-v-post/',task:'Contrast majority and dissent and distinguish possessory acquisition from land estates.'}];const MORE_LESSON_CASES=[{"course":"Contracts","lesson":1,"name":"Hadley v. Baxendale","facts":"A mill's broken crankshaft was delayed in shipment; owners sought lost profits from the carrier.","question":"Are all consequential lost profits recoverable from a breach?","outcome":"The court limited recovery to foreseeable loss arising naturally or within parties' contemplation when contracting.","reason":"Foreseeability of special circumstances affects consequential damages.","task":"Identify what notice to the carrier could have changed the analysis.","source":"https://www.bailii.org/ew/cases/EWHC/Exch/1854/J70.html"},{"course":"Torts","lesson":2,"name":"MacPherson v. Buick Motor Co.","facts":"An automobile wheel collapsed and injured a purchaser; the manufacturer had bought the wheel from another supplier.","question":"Was a direct contract with the manufacturer essential to an ordinary negligence claim?","outcome":"The New York Court of Appeals permitted negligence liability without contractual privity for a foreseeably dangerous defective product.","reason":"A manufacturer may owe a duty of care to foreseeable users beyond direct contracting parties.","task":"Distinguish negligent product manufacture from modern strict product liability.","source":"https://law.justia.com/cases/new-york/court-of-appeals/1916/217-n-y-382-1916.html"},{"course":"Civil Procedure","lesson":2,"name":"Taylor v. Sturgell","facts":"Different individuals brought Freedom of Information Act litigation over the same documents.","question":"Does a prior judgment ordinarily bind a new litigant who was not a party?","outcome":"The Supreme Court rejected broad virtual representation and reaffirmed limited exceptions to the rule against nonparty preclusion.","reason":"Due process limits binding a person to another's judgment.","task":"Identify the recognized exceptions and distinguish claim from issue preclusion.","source":"https://www.law.cornell.edu/supremecourt/text/07-371"},{"course":"Criminal Law","lesson":2,"name":"United States v. Resendiz-Ponce","facts":"A defendant challenged an indictment for attempted illegal reentry because it did not describe the particular overt act.","question":"Must every attempted-offense indictment specify the precise overt act?","outcome":"The Supreme Court held that this indictment's use of 'attempted' and its factual allegations sufficiently informed the accused of the charge.","reason":"The word attempt can encompass the overt-act component, depending on the charging context.","task":"Contrast pleading sufficiency with the proof of intent and the substantial step.","source":"https://www.law.cornell.edu/supremecourt/text/05-998"},{"course":"Constitutional Law","lesson":1,"name":"Tinker v. Des Moines","facts":"Public-school students wore black armbands to protest the Vietnam War; school officials suspended them.","question":"Can a public school prohibit peaceful political expression without evidence of substantial disruption?","outcome":"The Supreme Court protected the students' expression where the record did not establish material and substantial interference.","reason":"Student speech has distinctive standards; do not automatically transpose them to all public forums.","task":"Apply the substantial-disruption standard and compare government forum doctrines.","source":"https://www.law.cornell.edu/supremecourt/text/393/503"},{"course":"Property","lesson":3,"name":"Van Sandt v. Royster","facts":"A purchaser discovered an underground sewer crossing her property to serve neighboring lots formerly under common ownership.","question":"Can an easement arise from prior use despite absence of an express grant?","outcome":"The Kansas Supreme Court recognized an implied easement under the circumstances of prior common use and reasonable necessity.","reason":"Prior use, apparent or discoverable character, severance and necessity matter.","task":"Compare implied easement from prior use with necessity and prescription.","source":"https://law.justia.com/cases/kansas/supreme-court/1938/33-475-0.html"}];
const ADVANCED_LESSON_CASES=[{"course":"Criminal Law","lesson":5,"name":"Nix v. Williams","facts":"After unconstitutional police questioning, evidence of a victim's body was found while a large independent search was already underway.","question":"Can evidence be admitted if a lawful search would inevitably have found it?","outcome":"The Supreme Court held that evidence concerning the body was admissible because it would inevitably have been discovered through lawful search efforts.","reason":"The government must show inevitable discovery by a preponderance of the evidence; speculation is insufficient.","task":"Compare inevitable discovery with independent source and state what search evidence matters.","source":"https://www.law.cornell.edu/supremecourt/text/467/431"},{"course":"Property","lesson":6,"name":"Kelo v. City of New London","facts":"A city used eminent domain in connection with a broader economic redevelopment plan, with property ultimately planned for private development.","question":"Does the federal Public Use Clause categorically prohibit economic-development takings involving private use?","outcome":"The Supreme Court upheld the redevelopment plan's public purpose under the federal constitution, while recognizing that states can impose more restrictive limits.","reason":"Public use and just compensation are separate requirements, and stricter state constraints may apply.","task":"Analyze the majority and dissents; research whether the governing state imposes stricter public-use rules.","source":"https://www.law.cornell.edu/supremecourt/text/04-108"}];
const NEW_LESSON_CASES=[{"course":"Civil Procedure","lesson":6,"name":"Erie Railroad Co. v. Tompkins","facts":"A Pennsylvania resident injured by a train in Pennsylvania brought a diversity case in federal court and sought to rely on federal general common law.","question":"Could the federal diversity court use a general federal common-law negligence rule instead of controlling state substantive law?","outcome":"The Supreme Court rejected federal general common law and required application of state substantive law in diversity proceedings.","reason":"The Erie doctrine distinguishes substantive state law from federal procedural governance, refined by later decisions.","task":"Explain the substantive/procedural distinction and identify the controlling law.","source":"https://www.law.cornell.edu/supremecourt/text/304/64"},{"course":"Constitutional Law","lesson":7,"name":"Washington v. Davis","facts":"Applicants challenged a police-department test that disproportionately excluded Black applicants, alleging an equal-protection violation.","question":"Is disparate impact alone ordinarily enough for a constitutional equal-protection challenge to a facially neutral test?","outcome":"The Supreme Court held that discriminatory impact alone did not establish the constitutional violation; discriminatory purpose mattered.","reason":"The constitutional inquiry differs from some statutory anti-discrimination frameworks.","task":"Separate impact evidence, proof of discriminatory purpose, and possible statutory claims.","source":"https://www.law.cornell.edu/supremecourt/text/426/229"}];
const DOCTRINE_CASES=[{"course":"Civil Procedure","lesson":7,"name":"Bell Atlantic Corp. v. Twombly","facts":"Telephone customers alleged that major companies conspired to restrain trade, relying primarily on allegations of parallel business conduct.","question":"Do conclusory assertions of agreement without plausible supporting facts ordinarily suffice?","outcome":"The Supreme Court required enough factual matter to make the asserted antitrust agreement plausible rather than merely conceivable.","reason":"Pleading plausibility concerns adequately alleged facts, not proof by a preponderance at the pleading stage.","task":"Rewrite a conclusory complaint paragraph using relevant, noninvented factual allegations.","source":"https://www.law.cornell.edu/supremecourt/text/05-1126"},{"course":"Constitutional Law","lesson":8,"name":"United States v. Lopez","facts":"A student was prosecuted under a federal statute prohibiting firearm possession in a school zone; the challenged law did not require a commerce connection in each case.","question":"Was this federal prohibition as enacted sustained under Congress's Commerce Clause authority?","outcome":"The Supreme Court held the Gun-Free School Zones Act as enacted exceeded Congress's commerce power.","reason":"The decision distinguished economic activity and emphasized limits on aggregating non-economic local conduct.","task":"Discuss enumerated powers and distinguish later commerce cases.","source":"https://www.law.cornell.edu/supremecourt/text/514/549"}];
const NEXT_CASES=[{"course":"Civil Procedure","lesson":8,"name":"Celotex Corp. v. Catrett","facts":"An asbestos plaintiff opposed summary judgment after the defendant argued she lacked adequate evidence on a necessary element of her claim.","question":"Can a summary-judgment movant point to an absence of evidence on an element the other party must prove?","outcome":"The Supreme Court held a movant need not always produce affirmative evidence negating an opponent's claim and may point to an absence of proof on an essential element.","reason":"Rule 56 burdens and the evidentiary record govern; do not mistake legal sufficiency for resolving witness credibility.","task":"Identify what evidence the nonmovant must present and what factual disputes remain.","source":"https://www.law.cornell.edu/supremecourt/text/477/317"},{"course":"Criminal Law","lesson":8,"name":"Miranda v. Arizona","facts":"Police questioned suspects in custody without the procedural warnings later required by the Court before custodial interrogation.","question":"What procedural safeguards apply to custodial questioning when prosecutors seek to use the statements?","outcome":"The Supreme Court established Miranda safeguards for custodial interrogation, subject to subsequent doctrinal limitations.","reason":"Analyze custody, interrogation, warnings, waiver and remedies separately from the Sixth Amendment right to counsel.","task":"Compare precharge interrogation and postattachment Sixth Amendment situations.","source":"https://www.law.cornell.edu/supremecourt/text/384/436"}];
const WAVE_CASES=[{"course":"Constitutional Law","lesson":10,"name":"Lujan v. Defenders of Wildlife","facts":"Environmental groups challenged a federal agency rule but could not establish concrete plans connecting members to the threatened locations.","question":"Can generalized concern without sufficiently concrete injury establish federal Article III standing?","outcome":"The Supreme Court found standing lacking because the required injury showing was insufficient.","reason":"Article III standing requires injury in fact, traceability and redressability.","task":"Analyze member injury and possible remedies without assuming a policy disagreement alone creates standing.","source":"https://www.law.cornell.edu/supremecourt/text/504/555"},{"course":"Property","lesson":10,"name":"Boomer v. Atlantic Cement Co.","facts":"Neighbors challenged dirt, smoke, and vibration produced by a cement plant, seeking an injunction and damages.","question":"Must a court automatically shut down a business whenever a private nuisance is established?","outcome":"The New York Court of Appeals permitted a permanent-damages remedy instead of an unconditional injunction.","reason":"A nuisance determination and selection of equitable remedy are separate questions.","task":"Explain the majority's remedy choice and arguments for an injunction.","source":"https://law.justia.com/cases/new-york/court-of-appeals/1970/26-n-y-2d-219-0.html"}];
const CLASSIC_CASES=[{"course":"Civil Procedure","lesson":10,"name":"Wal-Mart Stores, Inc. v. Dukes","facts":"Employees sought certification of a large nationwide class challenging discretionary employment decisions at multiple stores.","question":"Was broad class certification justified without a common answer tying together the challenged decisions?","outcome":"The Supreme Court rejected the proposed class certification, emphasizing the need for common contentions capable of classwide resolution.","reason":"Rule 23 commonality requires more than many plaintiffs presenting related grievances.","task":"Compare common questions, representative proof and individual supervisor discretion.","source":"https://www.law.cornell.edu/supremecourt/text/10-277"},{"course":"Criminal Law","lesson":10,"name":"In re Winship","facts":"A juvenile was adjudicated delinquent based on findings under a preponderance standard for acts that would be criminal if committed by an adult.","question":"Must every element of a criminal offense be established beyond reasonable doubt in this delinquency proceeding?","outcome":"The Supreme Court held that due process requires proof beyond a reasonable doubt of every fact necessary to constitute the charged criminal act.","reason":"Reasonable doubt is a constitutional safeguard against erroneous criminal adjudication.","task":"Explain why a jury instruction shifting the burden of intent is problematic.","source":"https://www.law.cornell.edu/supremecourt/text/397/358"}];
const CURRENT_CASES=[{"course":"Torts","lesson":11,"name":"New York Times Co. v. Sullivan","facts":"A public official sued over inaccuracies in an advertisement criticizing official responses to civil-rights demonstrations.","question":"Could a public official recover for a defamatory falsehood about official conduct without proving knowing or reckless falsity?","outcome":"The Supreme Court held that a public official must prove actual malice for the covered defamation claim.","reason":"Actual malice means knowledge of falsity or reckless disregard for truth, not personal hostility.","task":"Apply the constitutional fault standard to the newspaper's evidence.","source":"https://www.law.cornell.edu/supremecourt/text/376/254"},{"course":"Constitutional Law","lesson":12,"name":"Kennedy v. Bremerton School District","facts":"A public-school football coach challenged discipline after praying at midfield following games; the parties disputed the nature and impact of the expression.","question":"Did the Court continue using the Lemon and endorsement tests as its controlling Establishment Clause framework?","outcome":"The Supreme Court ruled for the coach and disapproved reliance on the Lemon and endorsement approaches, emphasizing history and tradition.","reason":"Distinguish private religious expression from government coercion or sponsored exercises; later factual contexts may differ.","task":"Compare a personal postgame prayer with an officially directed mandatory religious exercise.","source":"https://www.law.cornell.edu/supremecourt/text/21-418"}];
const COMPANION_CASES=[{"course":"Torts","lesson":12,"name":"Vosburg v. Putney","facts":"A school pupil kicked another pupil during class, aggravating an existing injury.","question":"Does battery require intending the full severity of the resulting harm?","outcome":"The court recognized liability arising from the unlawful intentional contact, despite the unexpected severity of the injury.","reason":"Distinguish intention to make contact from intention to cause a particular injury.","task":"Analyze consent, the classroom setting, and the scope of resulting liability.","source":"https://law.justia.com/cases/wisconsin/supreme-court/1891/80-wis-523-0.html"},{"course":"Constitutional Law","lesson":13,"name":"Mathews v. Eldridge","facts":"An agency terminated disability benefits following documentary review without a pretermination evidentiary hearing.","question":"Is a live evidentiary hearing always required before disability benefits are terminated?","outcome":"The Supreme Court found the procedures sufficient in that setting, applying a three-factor balancing framework.","reason":"Consider private interests, erroneous-deprivation risk and value of safeguards, and governmental burdens.","task":"Apply the three factors to a dispute involving conflicting eyewitness accounts.","source":"https://www.law.cornell.edu/supremecourt/text/424/319"}];
const INLINE_CASE_MAP={'Contracts':0,'Torts':0,'Civil Procedure':0,'Criminal Law':0,'Constitutional Law':0,'Property':0};
const showCourse=i=>{const c=courses[i];shell('<div class="pagehead"><span class="gold-label">LEVEL 2 · '+esc(c.id)+'</span><h1>'+esc(c.title)+'</h1></div><div class="level-list">'+c.lessons.map((l,j)=>'<button class="level-row" data-l2lesson="'+j+'"><span class="level-text"><strong>'+esc(l.title)+'</strong><small>'+(record[l.id]?.correct?'Lesson check passed':'Study and practice')+'</small></span><span class="level-arrow">›</span></button>').join('')+'</div><button id="l2back" class="button secondary">All Level 2 courses</button>','courses');document.querySelectorAll('[data-l2lesson]').forEach(b=>b.onclick=()=>showLesson(i,+b.dataset.l2lesson));document.querySelector('#l2back').onclick=home};
const showLesson=(i,j)=>{const l=courses[i].lessons[j];const linked=COMPANION_CASES.find(c=>c.course===courses[i].title&&c.lesson===j)||CURRENT_CASES.find(c=>c.course===courses[i].title&&c.lesson===j)||CLASSIC_CASES.find(c=>c.course===courses[i].title&&c.lesson===j)||WAVE_CASES.find(c=>c.course===courses[i].title&&c.lesson===j)||NEXT_CASES.find(c=>c.course===courses[i].title&&c.lesson===j)||DOCTRINE_CASES.find(c=>c.course===courses[i].title&&c.lesson===j)||NEW_LESSON_CASES.find(c=>c.course===courses[i].title&&c.lesson===j)||ADVANCED_LESSON_CASES.find(c=>c.course===courses[i].title&&c.lesson===j)||MORE_LESSON_CASES.find(c=>c.course===courses[i].title&&c.lesson===j)||(((courses[i].title==='Constitutional Law'||courses[i].title==='Property')?j===5:j===0)?INLINE_CASES.find(c=>c.course===courses[i].title):null);const researchCase=courses[i].title==='Legal Research & Writing'&&j===0?INLINE_CASES.find(c=>c.course==='Civil Procedure'):null;shell('<div class="pagehead"><span class="gold-label">LEVEL 2 · '+esc(courses[i].title)+'</span><h1>'+esc(l.title)+'</h1></div><div class="review-item"><h3>Core doctrine</h3><p>'+esc(l.reading)+'</p></div>'+(researchCase?'<div class="review-item"><h3>Case research lab: '+esc(researchCase.name)+'</h3><p>Read the actual decision and prepare a case brief: procedural history, facts, issue, holding, controlling rule, reasoning, and treatment by later courts. Distinguish the historical holding from current doctrine.</p><p><a href="'+researchCase.source+'" target="_blank" rel="noopener noreferrer">Read original judicial opinion</a></p></div>':'')+(linked?'<div class="review-item"><h3>Real case: '+esc(linked.name)+'</h3><p>'+esc(linked.facts)+'</p><p><strong>Predict:</strong> '+esc(linked.question)+'</p><textarea id="inlineCaseReason" class="writing-field" rows="4" placeholder="Write your reasoning before revealing"></textarea><button id="inlineCaseReveal" class="gold-button">Reveal actual court decision</button><div id="inlineCaseResult" role="status"></div></div>':'')+'<div class="review-item"><h3>Applied legal problem</h3><p>'+esc(l.problem)+'</p><label for="l2draft">Your written analysis (practice, not graded)</label><textarea id="l2draft" class="writing-field" rows="9"></textarea></div><div class="review-item"><h3>Knowledge check</h3><p>'+esc(l.question)+'</p>'+l.options.map((o,k)=>'<label style="display:block;margin:10px 0"><input type="radio" name="l2choice" value="'+k+'"> '+esc(o)+'</label>').join('')+'<button id="l2submit" class="gold-button">Check answer</button><p id="l2result" role="status"></p></div><button id="l2back" class="button secondary">Back to course</button>','courses');if(linked){document.querySelector('#inlineCaseReveal').onclick=()=>{const reasoning=document.querySelector('#inlineCaseReason').value.trim(),out=document.querySelector('#inlineCaseResult');if(reasoning.length<35){out.textContent='Explain your prediction in at least 35 characters before revealing the court decision.';return}out.textContent=linked.outcome+' Legal reasoning: '+linked.reason+' Writing task: '+linked.task+' ';const a=document.createElement('a');a.href=linked.source;a.textContent='Read court decision';a.rel='noopener noreferrer';a.target='_blank';out.append(a)}};const draft=document.querySelector('#l2draft');draft.value=record[l.id]?.draft||'';draft.oninput=()=>{record[l.id]={...(record[l.id]||{}),draft:draft.value};save()};document.querySelector('#l2submit').onclick=()=>{const chosen=document.querySelector('input[name="l2choice"]:checked');if(!chosen){document.querySelector('#l2result').textContent='Choose an answer first.';return}const correct=+chosen.value===l.answer;record[l.id]={...(record[l.id]||{}),correct:correct||(record[l.id]?.correct||false)};const persisted=save();document.querySelector('#l2result').textContent=(correct?'Correct. ':'Not yet. ')+l.why+(persisted?'':' Warning: progress could not be saved.');};document.querySelector('#l2back').onclick=()=>{record[l.id]={...(record[l.id]||{}),draft:draft.value};save();showCourse(i)}};home();}
